            data-filled={i < n}
            className={`size-2.5 rounded-full transition-colors ${i < n ? 'bg-stone-700' : 'bg-stone-300'}`}
          />
        ))}
      </div>
      <p className="text-xs text-stone-500">
        {phase === 'long' ? 'Long break earned' : `${n} of ${SESSIONS_PER_CYCLE} until long break`}
